#!/usr/bin/env bash
# Behavioral regressions for ask-user authority instructions generated by fm-brief.
set -u

# shellcheck source=tests/lib.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

BRIEF="$ROOT/bin/fm-brief.sh"
TMP_ROOT=$(fm_test_tmproot fm-ask-user-authority)

test_primary_and_secondmate_instruction_generation() {
  local home ship charter
  home="$TMP_ROOT/home"
  mkdir -p "$home/data"

  FM_HOME="$home" FM_ROOT_OVERRIDE="$ROOT" \
    "$BRIEF" authority-worker sample --mode no-mistakes >/dev/null 2>&1
  ship="$home/data/authority-worker/brief.md"
  assert_grep 'ask-user findings are never yours to answer' "$ship" \
    "generated implementation brief lets the worker own an ask-user decision"
  assert_grep "Firstmate applies \`ask-user-authority\` and obtains any required captain decision" "$ship" \
    "generated implementation brief bypasses the primary authority owner"
  # shellcheck disable=SC2016 # Backticks are literal generated Markdown.
  assert_grep 'NEVER pass `--yes` (or `-y`) to `no-mistakes axi run` or `no-mistakes axi respond`' "$ship" \
    "generated implementation brief does not prohibit silent ask-user auto-resolution"
  assert_grep 'It auto-resolves every gate including ask-user findings with no escalation' "$ship" \
    "generated implementation brief does not explain the ask-user authority bypass"
  assert_no_grep 'the captain, not you, owns the ask-user decisions' "$ship" \
    "generated implementation brief retained conflicting captain-only wording"
  assert_grep 'standing answers and captain-facing report questions' "$ship" \
    "generated worker brief does not point recurring questions at the policy owner"
  assert_no_grep 'Machine-limit Test failure' "$ship" \
    "generated worker brief duplicated the supervisor standing-answer table"
  assert_no_grep 'Record the matched kind' "$ship" \
    "generated worker brief transferred repeat-question decisions to the worker"
  # shellcheck disable=SC2016 # Backticks are literal generated Markdown.
  assert_grep 'one `prior: <finding-id> <key>` line per finding identical to one firstmate already decided' "$ship" \
    "generated worker brief gives no way to cite an already-decided identical finding"
  assert_grep 'Those lines are hints for firstmate, never your answer' "$ship" \
    "generated worker brief lets a standing-answer hint stand in for firstmate's decision"

  mkdir -p "$home/config/brief-addenda"
  printf '%s\n' '## Standing answers' '' '| Recurring kind | Standing answer |' '| --- | --- |' \
    '| Sample registry drift | Include the regenerated registry. |' >"$home/config/brief-addenda/sample.md"
  FM_HOME="$home" FM_ROOT_OVERRIDE="$ROOT" \
    "$BRIEF" authority-addendum sample --mode no-mistakes >/dev/null 2>&1
  assert_grep '| Sample registry drift | Include the regenerated registry. |' "$home/data/authority-addendum/brief.md" \
    "project standing-answer table from the private addendum did not reach the worker brief"
  assert_no_grep 'Machine-limit Test failure' "$home/data/authority-addendum/brief.md" \
    "project addendum brief duplicated the supervisor standing-answer table"

  FM_HOME="$home" FM_ROOT_OVERRIDE="$ROOT" FM_SECONDMATE_CHARTER='Handle sample work.' \
    "$BRIEF" authority-mate --secondmate --no-projects >/dev/null 2>&1
  charter="$home/data/authority-mate/brief.md"
  # shellcheck disable=SC2016 # Backticks are literal generated Markdown.
  assert_grep 'The local `AGENTS.md` is your job description' "$charter" \
    "generated secondmate charter does not load the tracked authority boundary"
  assert_no_grep 'continuous frame-by-frame monitoring' "$charter" \
    "generated secondmate charter duplicated the detailed authority procedure"
  pass "primary workers and secondmates receive the authority rule through generated instructions"
}

test_worker_settle_and_pre_gate_checks_reach_every_gate_variant() {
  local home id brief args owner
  home="$TMP_ROOT/settle-home"
  mkdir -p "$home/data"

  for args in 'no-mistakes' 'no-mistakes --pr manual' 'no-mistakes --forge gerrit'; do
    id="settle-$(printf '%s' "$args" | tr -c 'a-z\n' '-')"
    # shellcheck disable=SC2086 # Word splitting supplies the variant's flags.
    FM_HOME="$home" FM_ROOT_OVERRIDE="$ROOT" "$BRIEF" "$id" sample --mode $args >/dev/null 2>&1 \
      || fail "the $args brief should scaffold"
    brief="$home/data/$id/brief.md"
    assert_grep 'Settle informational and style review findings yourself, without going up' "$brief" \
      "the $args worker cannot settle informational and style findings"
    assert_grep 'Security, data-loss, scope, and irreversible findings always escalate, and so does any doubt' "$brief" \
      "the $args worker lost the always-escalate boundary"
    assert_grep 'list it as a numbered follow-up in your done report' "$brief" \
      "the $args worker is not told to record a settled finding"
    assert_grep 'Beyond that one standing answer, ask-user findings are never yours to answer' "$brief" \
      "the $args worker may now answer ask-user findings outside the standing answer"
    assert_grep "except any standing answer your Definition of done has you settle yourself" "$brief" \
      "the $args worker's rule 6 contradicts the worker-settle rule"
    # shellcheck disable=SC2016 # Backticks are literal generated Markdown.
    assert_grep 'Before your first `no-mistakes axi run` for this task, run the project'"'"'s lint and the targeted tests covering your change, never a full suite' "$brief" \
      "the $args worker is not told to run cheap local checks before the first gate"
    assert_no_grep 'neither fixing nor leaving it changes behavior' "$brief" \
      "the $args brief restated the qualification the policy owner states once"
  done

  # The brief routes to the policy owner by path, so that path must resolve.
  # shellcheck disable=SC2016 # Backticks are literal generated Markdown.
  owner=$(grep -o '`[^`]*ask-user-authority/SKILL\.md`' "$brief" | head -n 1 | tr -d '`')
  [ -n "$owner" ] || fail "the worker-settle rule names no policy owner path"
  assert_present "$owner" "the worker-settle rule points at a missing policy owner"

  # A mode that runs no pipeline has no gate to settle at or to check before.
  for args in direct-PR local-only; do
    FM_HOME="$home" FM_ROOT_OVERRIDE="$ROOT" "$BRIEF" "settle-$args" sample --mode "$args" >/dev/null 2>&1 \
      || fail "the $args brief should scaffold"
    brief="$home/data/settle-$args/brief.md"
    assert_no_grep 'Settle informational and style review findings' "$brief" \
      "a $args worker was given a pipeline gate rule"
    assert_no_grep 'run the project'"'"'s lint and the targeted tests covering your change' "$brief" \
      "a $args worker was given a pre-gate step with no gate after it"
  done
  pass "every no-mistakes variant carries worker-settle and pre-gate checks; modes with no pipeline do not"
}

test_primary_and_secondmate_instruction_generation
test_worker_settle_and_pre_gate_checks_reach_every_gate_variant
